"""Operations on posts: what each one checks before it writes."""

from typing import Any

from app.documents import problems
from app.dtos.post import PostCreate, PostRead, PostUpdate
from app.entities.post import Post, PostComment
from app.errors import ConflictError, FieldError, NotFoundError, ValidationFailedError
from app.paging import Page
from app.unit_of_work import UnitOfWork

# Columns a client may send: the database fills the others
_FIELDS = frozenset({"title", "section", "slug", "status", "kind", "priority", "views", "ratio", "price", "day", "author", "reviewers", "related", "comments", "seo", "extra", "cover", "either"})

# What the documents inside each field must be
_RULES: dict[str, dict[str, Any]] = {
    "reviewers": {"items": {}},
    "related": {"items": {}},
    "comments": {"items": {"fields": {"text": {"required": True, "max_length": 500, "min_length": 1}, "stars": {"min": 1, "max": 5}, "answers": {"items": {}}}}},
    "seo": {"fields": {"description": {}, "key words": {"items": {}}}},
}


class PostService:
    """Operations on posts. Repositories commit every write."""

    def __init__(self, uow: UnitOfWork) -> None:
        self._uow = uow

    async def _validate_all(self, values: dict[str, Any], current: Post | None) -> None:
        """Checks the values against the rules of the "posts" table; raises ValidationFailedError with every problem."""
        creating = current is None
        errors: list[FieldError] = []
        for name in values.keys() - _FIELDS:
            errors.append(FieldError(name, "is not a field of Post"))
        if not creating:
            for name in values.keys() & {"id", "created_at", "token"}:
                errors.append(FieldError(name, "cannot be changed"))
        value = values.get("title")
        if value is None:
            if creating or "title" in values:
                errors.append(FieldError("title", "is required"))
        else:
            if isinstance(value, str) and len(value) > 80:
                errors.append(FieldError("title", "is longer than 80 characters"))
        value = values.get("section")
        if value is None:
            if "section" in values and not creating:
                errors.append(FieldError("section", "cannot be empty"))
        value = values.get("slug")
        if value is None:
            if creating or "slug" in values:
                errors.append(FieldError("slug", "is required"))
        value = values.get("status")
        if value is None:
            if "status" in values and not creating:
                errors.append(FieldError("status", "cannot be empty"))
        value = values.get("kind")
        if value is None:
            if creating or "kind" in values:
                errors.append(FieldError("kind", "is required"))
        value = values.get("priority")
        if value is None:
            if "priority" in values and not creating:
                errors.append(FieldError("priority", "cannot be empty"))
        value = values.get("views")
        if value is None:
            if "views" in values and not creating:
                errors.append(FieldError("views", "cannot be empty"))
        else:
            if not value >= 0:
                errors.append(FieldError("views", "must be >= 0"))
        value = values.get("ratio")
        if value is not None:
            if not value > 0:
                errors.append(FieldError("ratio", "must be > 0"))
            if not value < 1000:
                errors.append(FieldError("ratio", "must be < 1000"))
        value = values.get("price")
        if value is None:
            if creating or "price" in values:
                errors.append(FieldError("price", "is required"))
        value = values.get("day")
        if value is None:
            if creating or "day" in values:
                errors.append(FieldError("day", "is required"))
        value = values.get("author")
        if value is None:
            if creating or "author" in values:
                errors.append(FieldError("author", "is required"))
        value = values.get("reviewers")
        if value is not None:
            errors += problems(value, _RULES["reviewers"], "reviewers")
        value = values.get("related")
        if value is not None:
            errors += problems(value, _RULES["related"], "related")
        value = values.get("comments")
        if value is not None:
            errors += problems(value, _RULES["comments"], "comments")
        value = values.get("seo")
        if value is not None:
            errors += problems(value, _RULES["seo"], "seo")
        value = values.get("either")
        if value is None:
            if "either" in values and not creating:
                errors.append(FieldError("either", "cannot be empty"))
        if errors:
            raise ValidationFailedError("Post", errors)

    async def _check_unique(self, values: dict[str, Any], current: Post | None) -> None:
        """Values that must be unique are not taken by another row."""
        slug = values["slug"] if "slug" in values else (current.slug if current is not None else None)
        if slug is not None:
            other = await self._uow.posts.find_by_slug(slug)
            if other is not None and (current is None or other.id != current.id):
                raise ConflictError("Post", "slug is already taken", ("slug",))

    async def _check(self, values: dict[str, Any], current: Post | None) -> None:
        """Every check before a write: the values, the rows they point to, the unique values."""
        await self._validate_all(values, current)
        await self._check_unique(values, current)

    async def _find(self, id: str) -> Post:
        """The Post with this key; NotFoundError when there is none."""
        entity = await self._uow.posts.find_by_id(id)
        if entity is None:
            raise NotFoundError("Post", id)
        return entity

    @staticmethod
    def _read(entity: Post) -> PostRead:
        """The Post as services return it."""
        return PostRead.model_validate(entity)

    async def create_post(self, data: PostCreate) -> PostRead:
        """Stores a new Post after checking it."""
        values = data.model_dump(exclude_unset=True)
        await self._check(values, None)
        created = await self._uow.posts.insert(Post(**values))
        return self._read(created)

    async def get_post(self, id: str) -> PostRead:
        """The Post with this key; NotFoundError when there is none."""
        return self._read(await self._find(id))

    async def list_posts(self, offset: int = 0, limit: int = 50) -> Page[PostRead]:
        """A page of posts, by primary key."""
        page = await self._uow.posts.list(offset, limit)
        return Page(items=[self._read(entity) for entity in page.items], total=page.total, offset=page.offset, limit=page.limit)

    async def update_post(self, id: str, data: PostUpdate) -> PostRead:
        """Changes the given values of a Post."""
        values = data.model_dump(exclude_unset=True)
        current = await self._find(id)
        await self._check(values, current)
        for name, value in values.items():
            setattr(current, name, value)
        updated = await self._uow.posts.update(current)
        return self._read(updated)

    async def delete_post(self, id: str) -> None:
        """Deletes a Post."""
        current = await self._find(id)
        await self._uow.posts.delete(current)

    async def find_post_by_slug(self, slug: str) -> PostRead | None:
        """The Post with this slug, or None."""
        entity = await self._uow.posts.find_by_slug(slug)
        return self._read(entity) if entity is not None else None

    async def add_reviewer(self, id: str, reviewer: Any) -> PostRead:
        """Adds an item to reviewers."""
        errors = problems([reviewer], _RULES["reviewers"], "reviewers")
        if errors:
            raise ValidationFailedError("Post", errors)
        await self._find(id)
        changed = await self._uow.posts.add_reviewer(id, reviewer)
        if changed is None:
            raise NotFoundError("Post", id)
        return self._read(changed)

    async def remove_reviewer(self, id: str, position: int) -> PostRead:
        """Removes an item from reviewers, by its position."""
        current = await self._find(id)
        if not (0 <= position < len(current.reviewers or [])):
            raise NotFoundError("Reviewer", position)
        changed = await self._uow.posts.remove_reviewer(id, position, len(current.reviewers))
        if changed is None:
            raise ConflictError("Post", "was changed by someone else since it was read", ("reviewers",))
        return self._read(changed)

    async def add_related(self, id: str, related: str) -> PostRead:
        """Adds an item to related."""
        errors = problems([related], _RULES["related"], "related")
        if errors:
            raise ValidationFailedError("Post", errors)
        await self._find(id)
        changed = await self._uow.posts.add_related(id, related)
        if changed is None:
            raise NotFoundError("Post", id)
        return self._read(changed)

    async def remove_related(self, id: str, related: str) -> PostRead:
        """Removes an item from related, by its value."""
        current = await self._find(id)
        if not (related in (current.related or [])):
            raise NotFoundError("Related", related)
        changed = await self._uow.posts.remove_related(id, related)
        if changed is None:
            raise NotFoundError("Post", id)
        return self._read(changed)

    async def add_comment(self, id: str, comment: PostComment) -> PostRead:
        """Adds an item to comments."""
        errors = problems([comment], _RULES["comments"], "comments")
        if errors:
            raise ValidationFailedError("Post", errors)
        await self._find(id)
        changed = await self._uow.posts.add_comment(id, comment)
        if changed is None:
            raise NotFoundError("Post", id)
        return self._read(changed)

    async def remove_comment(self, id: str, comment_id: str) -> PostRead:
        """Removes an item from comments, by its identifier."""
        current = await self._find(id)
        if not any(item["_id"] == comment_id for item in current.comments or []):
            raise NotFoundError("Comment", comment_id)
        changed = await self._uow.posts.remove_comment(id, comment_id)
        if changed is None:
            raise NotFoundError("Post", id)
        return self._read(changed)

