"""Rows for the tests: valid values for every column, and the rows they point to."""

from datetime import UTC, datetime
from decimal import Decimal
from typing import Any

from app.entities.animal import Animal
from app.entities.author import Author
from app.entities.post import Post
from app.unit_of_work import UnitOfWork


def new_author(n: int = 1, **values: Any) -> Author:
    """A valid Author that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"id": n, "name": f"name-{n}", "email": f"email-{n}"}
    return Author(**(defaults | values))


async def add_author(uow: UnitOfWork, n: int = 1) -> Author:
    """A stored Author."""
    return await uow.author.insert(new_author(n))


def new_post(n: int = 1, **values: Any) -> Post:
    """A valid Post that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"title": f"title-{n}", "section": f"section-{n}", "slug": f"slug-{n}", "status": "draft", "kind": "note", "priority": n, "views": n, "ratio": 1 + n % 998 + 0.5, "price": Decimal(f"{n % 10000}.50"), "day": datetime(2026, 1, n % 28 + 1, 12, 0, 0, tzinfo=UTC), "author": {"n": n}, "reviewers": [], "related": [], "comments": [{"text": f"text-{n}", "stars": 1 + n % 5, "answers": []}], "seo": {"description": f"description-{n}", "key words": []}, "extra": {"n": n}, "cover": bytes([n % 256]), "either": {"n": n}}
    return Post(**(defaults | values))


async def add_post(uow: UnitOfWork, n: int = 1) -> Post:
    """A stored Post."""
    return await uow.posts.insert(new_post(n))


def new_animal(n: int = 1, **values: Any) -> Animal:
    """A valid Animal that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"name": f"name-{n}"}
    return Animal(**(defaults | values))


async def add_animal(uow: UnitOfWork, n: int = 1) -> Animal:
    """A stored Animal."""
    return await uow.animal.insert(new_animal(n))
